using System;using System.IO;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using DazPose.Validation;
[InitializeOnLoad]public static class Day3Validation {
 static Day3Validation(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("Day3Validation.Active",false))EditorApplication.delayCall+=Finish;};}
 public static void Run(){try{if(!Application.dataPath.Replace('\\','/').Contains("/.dazposewizard/production-consolidation/"))throw new Exception("Disposable project required");var scene=EditorSceneManager.OpenScene(Day3SceneBuilder.ScenePath);var runner=UnityEngine.Object.FindObjectsByType<Day3RegressionRunner>(FindObjectsSortMode.None);if(runner.Length!=1)throw new Exception("Delivered saved runner missing or ambiguous");SessionState.SetBool("Day3Validation.Active",true);EditorApplication.EnterPlaymode();}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Finish(){SessionState.SetBool("Day3Validation.Active",false);try{var json=File.ReadAllText("TestOutput/day3/runtime.json");Debug.Log(json);EditorApplication.Exit(json.Contains("\"status\": \"passed\"")?0:1);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
